import { number, string, object, union, literal } from 'schematox'
import type { Infer } from 'schematox'

const CUID_LENGTH = 24

export type Timestamp = Infer<typeof timestamp>
export const timestamp = number()
  .min(-62135601840000 /* 31 December 0000 */)
  .max(4922895600000 /* 31 December 2126 */)
  .brand(['format', 'Milliseconds from 1970-01-01T00:00:00Z'] as const)

export type StoreEventId = Infer<typeof storeEventId>
export const storeEventId = number()
  .min(1)
  .max(Number.MAX_SAFE_INTEGER)
  .brand(['idFor', 'StoreEvent'] as const)

/**
 * Anonymous visitor id generated by the client (`crypto.randomUUID()`) and
 * sent as the `Authorization` header. A placeholder until registration exists.
 */
export type VisitorId = Infer<typeof visitorId>
export const visitorId = string()
  .minLength(8)
  .maxLength(64)
  .brand(['idFor', 'Visitor'] as const)

export type CommandId = Infer<typeof commandId>
export const commandId = string()
  .minLength(CUID_LENGTH)
  .maxLength(CUID_LENGTH)
  .brand(['idFor', 'Command'] as const)

export type MessageId = Infer<typeof messageId>
export const messageId = union([storeEventId, commandId])

export const STORE_EVENT_SHARED = {
  id: storeEventId,
  kind: string(),
  correlationId: messageId,
  causationId: messageId,
  issuedAt: timestamp,
}

export type StoreEventShared = Infer<typeof storeEventShared>
export const storeEventShared = object(STORE_EVENT_SHARED)

/* Domain specific ids */

export type GameId = Infer<typeof gameId>
export const gameId = string()
  .minLength(1)
  .maxLength(64)
  .brand(['idFor', 'Game'] as const)

export type RoundId = Infer<typeof roundId>
export const roundId = string()
  .minLength(CUID_LENGTH)
  .maxLength(CUID_LENGTH)
  .brand(['idFor', 'Round'] as const)

export type RollId = Infer<typeof rollId>
export const rollId = string()
  .minLength(CUID_LENGTH)
  .maxLength(CUID_LENGTH)
  .brand(['idFor', 'Roll'] as const)

export type RunId = Infer<typeof runId>
export const runId = string()
  .minLength(CUID_LENGTH)
  .maxLength(CUID_LENGTH)
  .brand(['idFor', 'Run'] as const)

export type DiceDirection = Infer<typeof diceDirection>
export const diceDirection = union([literal('over'), literal('under')])

export type RoadDifficulty = Infer<typeof roadDifficulty>
export const roadDifficulty = union([
  literal('easy'),
  literal('medium'),
  literal('hard'),
  literal('hardcore'),
])

export type CQRSHandlerKind = Infer<typeof cqrsHandlerKind>
export const cqrsHandlerKind = union([
  literal('projection'),
  literal('command'),
])
